def solution(text: str) -> str:
    """Returns the input string with alternating case starting with uppercase."""
    result = []
    for i, char in enumerate(text):
        if i % 2 == 0:
            result.append(char.upper())
        else:
            result.append(char.lower())
    return ''.join(result)
